#!/usr/bin/env bash
# File BARCLAY ROUND 3 into reports/2026-09-06 - the six seeds, then the sheet.
set -eu
PY="C:/Python313/python.exe"
L="Z:/ImageGenerator/Cartoon/scripts/report-log.py"
D="C:/Users/admin/AppData/Local/Temp/claude/Z--ImageGenerator/7e90a839-5703-42df-8007-3e3f206ae0ae/scratchpad/cast-studies/dog/round-3"

ASK="The founder: 'its a flamingo you did a terrible job you must perfect each character.' Round 3 for BARCLAY, against the judges' round-2 list: turn his head a FULL three-quarter into the room and draw the far eye whole, off the muzzle bridge, at least two-thirds the width of the near one; open both eyes wide and human with the worry carried by two raised inner brows; run the black lip-line band forward, unbroken, to finish directly under the front corner of the near eye; give him four separately contoured fingers and a thumb, no mitten and no claws; draw the USA flag pin legibly - canton, stars, bars, staff - on the near lapel and nowhere else; each drop ear a separate leather with a long wavy fringe, lifting clear of the shoulder; the coat in long layered directional strokes, not a field of spiky dashes; one unbroken glass rim with the cherry down inside below the liquid line; and no lettering, no blank rectangle and no crazed marble anywhere. And before rendering: re-cut Picture 2 so the whole head sits inside it with air, rebuild Picture 3 with no paint-outs, and rebuild Picture 1's head so the pose is DRAWN rather than hinted."

THOUGHT="The judges' three reference fixes were all made, one of them by the escalation their own PROCESS line authorises. (1) PICTURE 2 was re-cut (70,0,720,730) instead of (330,100,690,700), which had sliced the nose tip off at the tile edge; measured off a gridded copy, the head runs crown y=45, nose x=130, chin y=430, ear back x=540, and the lapel flag pin sits at x 628-700, y 628-690, so the new tile clears all of it with 40-60 px of air and nothing touching an edge. That taller cut catches the study's own raised glass and STIRRER in the corner - a pick in a reference - so the corner was rebuilt from the picture's own material 104 px higher up the same columns: blank paper over the paper half, the jacket's own weave and its slanting edge over the jacket half. No paint-out. (2) PICTURE 3: sc07 is dropped. Its mouth is OPEN, which fought the closed-mouth edit, and its tile carried a flat grey block over two lettered labels. All twelve retired plates were read at full size; sc01 is the one that crops tight on a CLOSED mouth with the lettered shelf row entirely above the crop (labels end y=800, crown starts y=855), so the tile is (620,818,420,344). The single label inside it, ACE RESERVE, was removed the way the judges asked - engraved bottle-glass cloned down from the same bottle's shoulder, never a block. (3) PICTURE 1: the judges asked for the re-cut Picture 2 head to be composited in 'turned further into the room than it is now', which pasting it cannot do - that is the same shallow turn round 2 pasted and the model flattened back to profile. Their PROCESS line authorises the escalation, so the three-quarter was borrowed from canon's ONLY true three-quarter of Barclay with both eyes whole and the mouth closed: canon/characters/dog/kit/head.png. It faces the reader's right, so it was MIRRORED - after which the muzzle points frame-left, the near ear lands where the plate's own ear is, and the far eye sits clear of the muzzle bridge. It was scaled 300/635 to the plate's own crown-to-jaw and seated crown-on-crown, nose-on-nose. It is graphite, so the prompt says outright that Picture 1's head is a rough paste-up whose ANGLE and PLACEMENT are law and whose quality is not. Three faults of the round-2 composite were also fixed in pixels rather than in words: the halo round the skull (the head is now cut by FINDING the kit sheet's paper - bright AND locally flat - then eroding 3 px, instead of by a hand polygon), the pale bushy lobe of the plate's old profile ear sticking out past the narrower three-quarter head (rebuilt from the back bar's own slat panelling tiled down), and the cocktail pick, whose column is now rebuilt by row-wise interpolation so the rim ellipse and the liquid line run straight through it, with the cherry re-seated below the liquid line. ONE CONTRADICTION in the judges' list was resolved and is flagged: it asks both for an iris 'pressed against the FRONT corner... front 40 percent' and for an iris 'near the CENTRE of the eye, not jammed into the corner', with both pupils aimed at one spot in the room. The centred version is the one consistent with the pose this round exists to get, so EDIT 2 takes it and keeps from the other only what does not conflict."

SET="scripts/cast-study.py via scripts/run-barclay-round3.sh, references built by scripts/make-barclay-round3-tiles.py - local/qwen-image-edit-2511, provider local, 4:5 -> 1344x1680, fast Lightning 8 steps, cfg 1.0, euler/simple, shift 3.0, 3 references (composited plate crop + re-cut study + sc01 head crop), 14 numbered EDITs, LOCAL_NEGATIVE verbatim (inert at cfg 1), tag study-barclay-r3."

file_one () {
  SEED="$1"; TITLE="$2"; VERDICT="$3"
  "$PY" "$L" "$D/barclay-seed$SEED.png" --date 2026-09-06 \
    --title "$TITLE" --ask "$ASK" --thought "$THOUGHT" --settings "$SET Seed $SEED." \
    --prompt-file "$D/barclay-seed$SEED.prompt.txt" --verdict "$VERDICT"
}

file_one 41 "Barclay character study round 3 seed 41 best the head finally turns all the way into the room" \
"BEST OF THE ROUND, and the best Barclay this project has drawn. The pose the last two rounds could not get is here: a FULL three-quarter, the far eye a complete open eye with its own lid, its own paper-white, its own iris and its own brow, set clear of the muzzle bridge with a finger's width of far cheek beside it, and both pupils aimed at the same spot in the room. Both inner brows lift in the pale domes the note asked for, so the worry is in the brows and not in a squint. Mouth closed; the lip-line is one unbroken true-black band that runs forward along the muzzle and hooks up at the corner. The nose is the blackest mark on the page. Freckles read in arcing rows, the ears are two separate leathers with fringe, the collar shows on both sides, the glass rim is unbroken with the ice cube inside and no pick, skewer or stem anywhere. STILL OPEN: the camera pushed in - the head takes about half the frame's height, not the third asked for, and the lapels are crowded at the bottom edge; the flag pin is AGAIN a blank pale triangle rather than a canton-and-bars flag; two bottle labels carry pseudo-writing and one small pale rectangle sits at the right edge; the marble crazes into a crackle field at the left; the cherry rides at the liquid line rather than fully below it; the fingers are only half separated; and the panelling behind his ear carries a soft vertical blur inherited from the paste-up seam."

file_one 44 "Barclay character study round 3 seed 44 reject a human bartender appeared behind the counter" \
"REJECT, and the most instructive failure of the six. A full HUMAN bartender - man, bow tie, waistcoat, hand on chin - is drawn behind the counter, with a table lamp, a wine glass and a hanging pendant lamp that belong to no canon room. Barclay himself slid back toward profile and grew a beaded collar round his neck. The service side of the counter has to be named as EMPTY in as many words; 'exactly one character' in the fence and 'no second dog, no figurine' in the edits did not stop a person appearing."

file_one 7 "Barclay character study round 3 seed 7 reject the room fell away and the coat went spotted" \
"REJECT. The model took its staging from Picture 2 instead of Picture 1: the bar is gone and he sits on blank paper, with a scribbled signature at the bottom edge. The coat is drawn in heavy round SPOTS rather than layered strokes, which reads as a spaniel and not a golden retriever, and the head fills the frame. Worth keeping for one thing only - it drew the most legible USA flag pin of the six, canton, stars and bars, on the near lapel. Whatever that seed did to the pin is what the other five need."

file_one 12 "Barclay character study round 3 seed 12 second best softer eyes and a glossy nose" \
"SECOND BEST. Same true three-quarter, both eyes whole with white showing round the iris, closed mouth, black lip band, room and prop all correct, one character only. Behind seed 41 on three counts: the far eye is smaller, the nose carries a broad glossy shine instead of one pinpoint highlight, and the near ear merges into the ruff. Same open faults as 41 - camera too close, blank-triangle pin, pseudo-writing on a label, crazed marble."

file_one 68 "Barclay character study round 3 seed 68 good pose sleepier eyes one lettered label" \
"PASS, third. The pose holds and the room, the glass and the single-character rule all hold; the ears are the cleanest pair of the six, each a separate leather lifting clear of the shoulder. Held back by sleepier, smaller eyes with heavier upper lids, a broad glossy nose highlight, a lip-line that thins to grey along the muzzle, and a bottle label carrying legible pseudo-text."

file_one 91 "Barclay character study round 3 seed 91 reject back to profile with a spotted coat" \
"REJECT. The head regressed to the old near-profile with only one eye drawn, and the coat went to heavy spots again. It did draw a clean USA flag - canton, stars and bars - but on the SHOULDER, which the note forbids, not on the lapel. The camera distance, ironically, is the best of the six."

"$PY" "$L" "$D/sheet.png" --date 2026-09-06 \
  --title "Barclay character study round 3 contact sheet six seeds beside the kit tiles" \
  --ask "$ASK" --thought "$THOUGHT" \
  --settings "$SET Seeds 41, 44, 7, 12, 68, 91 - 41 and 44 held from round 2 as the judges asked, four new." \
  --verdict "The round's one big win is structural: with the three-quarter DRAWN into Picture 1 from kit/head.png rather than prompted, four of six seeds came back with the head turned properly into the room and the far eye whole and off the muzzle bridge - the fault that has failed every previous round. Seed 41 is the best Barclay the project has: full three-quarter, both eyes open and human, both inner brows lifted, unbroken black lip band, black nose, two separate fringed ears, collar on both sides, unbroken glass rim with no pick. Seeds 12 and 68 are usable behind it. Three rejects, each a different lesson: 44 invented a HUMAN bartender (the empty service side must be named), 7 took Picture 2's blank-paper staging instead of Picture 1's room and drew a spotted coat, 91 fell back to profile. STILL OPEN AFTER THREE ROUNDS, and the round-4 list: the flag pin is a blank pale triangle in every seed that got the pose right, while the two seeds that drew a real flag (7 on the lapel, 91 on the shoulder) are the two that got other things wrong; the camera keeps pushing in to about half-frame instead of the third asked for, which the wider Picture 1 crop should now be tried against; bottle labels keep growing pseudo-writing and the marble keeps crazing; and the paste-up seam behind the skull still shows as a soft vertical blur in the panelling."
